UPDATE diseases SET severity = 'HIGH', treatment_en = 'Spray Captan @ 2g/L every 10-14 days. Remove mummified fruits and cankers. Prune infected branches.', treatment_bn = 'প্রতি ১০-১৪ দিনে ক্যাপ্টান ২ গ্রাম/লিটার স্প্রে করুন। মমিফাইড ফল এবং ক্যানকার সরান। আক্রান্ত শাখা ছাঁটাই করুন।', treatment_hi = 'हर 10-14 दिन में कैप्टन 2 ग्राम/लीटर स्प्रे करें। सूखे फल और कैंकर हटाएं। संक्रमित शाखाएं काटें।' WHERE model_class_label = 'Apple___Black_rot';
