UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Azoxystrobin @ 1ml/L or Pyraclostrobin @ 1ml/L at first sign. Practice crop rotation.', treatment_bn = 'প্রথম লক্ষণে অ্যাজোক্সিস্ট্রোবিন ১ মিলি/লিটার বা পাইরাক্লোস্ট্রোবিন ১ মিলি/লিটার স্প্রে করুন। ফসলের আবর্তন করুন।', treatment_hi = 'पहले लक्षण पर एज़ोक्सीस्ट्रोबिन 1 मिली/लीटर या पायराक्लोस्ट्रोबिन 1 मिली/लीटर स्प्रे करें। फसल चक्र अपनाएं।' WHERE model_class_label = 'Corn_(maize)___Cercospora_leaf_spot Gray_leaf_spot';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Spray Azoxystrobin @ 1ml/L or Propiconazole @ 1ml/L at first sign. Remove crop debris.', treatment_bn = 'প্রথম লক্ষণে অ্যাজোক্সিস্ট্রোবিন ১ মিলি/লিটার বা প্রোপিকোনাজল ১ মিলি/লিটার স্প্রে করুন। ফসলের ধ্বংসাবশেষ সরান।', treatment_hi = 'पहले लक्षण पर एज़ोक्सीस्ट्रोबिन 1 मिली/लीटर या प्रोपिकोनाजोल 1 मिली/लीटर स्प्रे करें। फसल का मलबा हटाएं।' WHERE model_class_label = 'Corn_(maize)___Northern_Leaf_Blight';
