UPDATE diseases SET severity = 'HIGH', treatment_en = 'Treat seeds with Streptocycline @ 0.5g/10L. Spray Copper oxychloride @ 3g/L every 15 days. Remove infected plants.', treatment_bn = '০.৫ গ্রাম/১০ লিটার স্ট্রেপ্টোসাইক্লিন দিয়ে বীজ শোধন করুন। প্রতি ১৫ দিনে কপার অক্সিক্লোরাইড ৩ গ্রাম/লিটার স্প্রে করুন। আক্রান্ত গাছ সরান।', treatment_hi = '0.5 ग्राम/10 लीटर स्ट्रेप्टोसाइक्लिन से बीजोपचार करें। हर 15 दिन में कॉपर ऑक्सीक्लोराइड 3 ग्राम/लीटर स्प्रे करें। संक्रमित पौधे हटाएं।' WHERE model_class_label = 'Cotton___Bacterial_Blight';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'No direct cure. Uproot and destroy infected plants. Control whitefly with Imidacloprid @ 0.3ml/L every 10 days.', treatment_bn = 'সরাসরি প্রতিকার নেই। আক্রান্ত গাছ উপড়ে ফেলে ধ্বংস করুন। প্রতি ১০ দিনে ইমিডাক্লোপ্রিড ০.৩ মিলি/লিটার দিয়ে সাদা মাছি নিয়ন্ত্রণ করুন।', treatment_hi = 'कोई सीधा इलाज नहीं। संक्रमित पौधों को उखाड़कर नष्ट करें। हर 10 दिन में इमिडाक्लोप्रिड 0.3 मिली/लीटर से सफेद मक्खी नियंत्रित करें।' WHERE model_class_label = 'Cotton___Curl_Virus';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Soil drench with Carbendazim @ 2g/L around the root zone. Apply Trichoderma viride @ 5kg/acre with organic manure.', treatment_bn = 'মূল অঞ্চলের চারপাশে কার্বেন্ডাজিম ২ গ্রাম/লিটার দিয়ে মাটি ভিজিয়ে দিন। জৈব সারের সাথে ট্রাইকোডার্মা ভিরিডি ৫ কেজি/একর প্রয়োগ করুন।', treatment_hi = 'जड़ क्षेत्र के आसपास कार्बेन्डाजिम 2 ग्राम/लीटर से मिट्टी भिगोएं। जैविक खाद के साथ ट्राइकोडर्मा विरिडी 5 किग्रा/एकड़ डालें।' WHERE model_class_label = 'Cotton___Fusarium_Wilt';
UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Cotton___Healthy';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Spray Myclobutanil @ 1ml/L or Mancozeb @ 2.5g/L every 14 days. Remove mummified berries and infected canes.', treatment_bn = 'প্রতি ১৪ দিনে মাইক্লোবুটানিল ১ মিলি/লিটার বা ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার স্প্রে করুন। মমিফাইড ফল এবং আক্রান্ত শাখা সরান।', treatment_hi = 'हर 14 दिन में माइक्लोबुटानिल 1 मिली/लीटर या मैंकोजेब 2.5 ग्राम/लीटर स्प्रे करें। सूखे फल और संक्रमित टहनियां हटाएं।' WHERE model_class_label = 'Grape___Black_rot';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'No cure. Remove severely affected vines. Prune affected branches. Apply Trichoderma to pruning wounds.', treatment_bn = 'কোন প্রতিকার নেই। মারাত্মক আক্রান্ত লতা সরান। আক্রান্ত শাখা ছাঁটাই করুন। ছাঁটাইয়ের ক্ষতে ট্রাইকোডার্মা প্রয়োগ করুন।', treatment_hi = 'कोई इलाज नहीं। गंभीर रूप से प्रभावित बेलें हटाएं। प्रभावित शाखाएं काटें। कटाई के घावों पर ट्राइकोडर्मा लगाएं।' WHERE model_class_label = 'Grape___Esca_(Black_Measles)';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Copper oxychloride @ 3g/L or Mancozeb @ 2.5g/L every 14 days. Remove infected leaves.', treatment_bn = 'প্রতি ১৪ দিনে কপার অক্সিক্লোরাইড ৩ গ্রাম/লিটার বা ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার স্প্রে করুন। আক্রান্ত পাতা সরান।', treatment_hi = 'हर 14 दिन में कॉपर ऑक्सीक्लोराइड 3 ग्राम/लीटर या मैंकोजेब 2.5 ग्राम/लीटर स्प्रे करें। संक्रमित पत्तियां हटाएं।' WHERE model_class_label = 'Grape___Leaf_blight_(Isariopsis_Leaf_Spot)';
UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Grape___healthy';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Spray Carbendazim 50% WP @ 1g/L or Mancozeb @ 2g/L at flowering and fruit-set stages. Prune affected branches and destroy.', treatment_bn = 'ফুল ও ফল ধরার পর্যায়ে কার্বেন্ডাজিম ৫০% ডব্লিউপি ১ গ্রাম/লিটার বা ম্যাঙ্কোজেব ২ গ্রাম/লিটার স্প্রে করুন। আক্রান্ত শাখা ছাঁটাই করে ধ্বংস করুন।', treatment_hi = 'फूल और फल बनने के समय कार्बेन्डाजिम 50% WP 1 ग्राम/लीटर या मैंकोजेब 2 ग्राम/लीटर स्प्रे करें। प्रभावित शाखाओं को काटकर नष्ट करें।' WHERE model_class_label = 'Mango___Anthracnose';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Prune affected parts 15cm below infection. Spray Copper oxychloride @ 3g/L. Apply Bordeaux paste on cut ends.', treatment_bn = 'সংক্রমণের ১৫ সেমি নিচে আক্রান্ত অংশ ছাঁটাই করুন। কপার অক্সিক্লোরাইড ৩ গ্রাম/লিটার স্প্রে করুন। কাটা প্রান্তে বোর্ডো পেস্ট লাগান।', treatment_hi = 'संक्रमण से 15 सेमी नीचे प्रभावित भाग काटें। कॉपर ऑक्सीक्लोराइड 3 ग्राम/लीटर स्प्रे करें। कटे सिरों पर बोर्डो पेस्ट लगाएं।' WHERE model_class_label = 'Mango___Bacterial_Canker';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Quinalphos 25% EC @ 2ml/L. Collect and destroy fallen twigs daily. Apply sticky traps.', treatment_bn = 'কুইনালফস ২৫% ইসি ২ মিলি/লিটার স্প্রে করুন। প্রতিদিন পড়ে যাওয়া ডাল সংগ্রহ করে ধ্বংস করুন। আঠালো ফাঁদ প্রয়োগ করুন।', treatment_hi = 'क्विनालफॉस 25% EC 2 मिली/लीटर स्प्रे करें। गिरी हुई टहनियों को रोज इकट्ठा करके नष्ट करें। चिपचिपे जाल लगाएं।' WHERE model_class_label = 'Mango___Cutting_Weevil';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Prune affected twigs 15cm below infection. Spray Copper oxychloride @ 3g/L every 15 days.', treatment_bn = 'সংক্রমণের ১৫ সেমি নিচে আক্রান্ত ডাল ছাঁটাই করুন। প্রতি ১৫ দিনে কপার অক্সিক্লোরাইড ৩ গ্রাম/লিটার স্প্রে করুন।', treatment_hi = 'संक्रमण से 15 सेमी नीचे प्रभावित टहनियां काटें। हर 15 दिन में कॉपर ऑक्सीक्लोराइड 3 ग्राम/लीटर स्प्रे करें।' WHERE model_class_label = 'Mango___Die_Back';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Imidacloprid 17.8% SL @ 0.3ml/L at new flush stage. Remove and burn affected twigs.', treatment_bn = 'নতুন ফ্লাশ পর্যায়ে ইমিডাক্লোপ্রিড ১৭.৮% এসএল ০.৩ মিলি/লিটার স্প্রে করুন। আক্রান্ত ডাল সরিয়ে পুড়িয়ে ফেলুন।', treatment_hi = 'नई फ्लश अवस्था में इमिडाक्लोप्रिड 17.8% SL 0.3 मिली/लीटर स्प्रे करें। प्रभावित टहनियों को हटाकर जलाएं।' WHERE model_class_label = 'Mango___Gall_Midge';
UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Mango___Healthy';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Wettable Sulphur @ 2g/L or Dinocap @ 1ml/L at panicle emergence stage. Repeat every 15 days.', treatment_bn = 'প্যানিকল ইমার্জেন্স পর্যায়ে ভেজা সালফার ২ গ্রাম/লিটার বা ডাইনোক্যাপ ১ মিলি/লিটার স্প্রে করুন। প্রতি ১৫ দিনে পুনরাবৃত্তি করুন।', treatment_hi = 'पैनिकल निकलने पर गीला सल्फर 2 ग्राम/लीटर या डाइनोकैप 1 मिली/लीटर स्प्रे करें। हर 15 दिन में दोहराएं।' WHERE model_class_label = 'Mango___Powdery_Mildew';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Control hoppers/aphids with Imidacloprid @ 0.3ml/L. Wash leaves with water. Improve air circulation.', treatment_bn = 'ইমিডাক্লোপ্রিড ০.৩ মিলি/লিটার দিয়ে হপার/এফিড নিয়ন্ত্রণ করুন। জল দিয়ে পাতা ধুয়ে দিন। বায়ু চলাচল উন্নত করুন।', treatment_hi = 'इमिडाक्लोप्रिड 0.3 मिली/लीटर से हॉपर/एफिड्स को नियंत्रित करें। पत्तियों को पानी से धोएं। वायु संचार बढ़ाएं।' WHERE model_class_label = 'Mango___Sooty_Mould';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'No cure. Remove and burn infected trees. Control Asian citrus psyllid with Imidacloprid @ 0.3ml/L every 15 days.', treatment_bn = 'কোন প্রতিকার নেই। আক্রান্ত গাছ সরিয়ে পুড়িয়ে ফেলুন। প্রতি ১৫ দিনে ইমিডাক্লোপ্রিড ০.৩ মিলি/লিটার দিয়ে এশিয়ান সাইট্রাস সাইলিড নিয়ন্ত্রণ করুন।', treatment_hi = 'कोई इलाज नहीं। संक्रमित पेड़ों को हटाकर जलाएं। हर 15 दिन में इमिडाक्लोप्रिड 0.3 मिली/लीटर से एशियाई साइट्रस साइलिड नियंत्रित करें।' WHERE model_class_label = 'Orange___Haunglongbing_(Citrus_greening)';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Mancozeb @ 2g/L or Carbendazim @ 1g/L every 10 days. Remove and destroy affected fruits.', treatment_bn = 'প্রতি ১০ দিনে ম্যাঙ্কোজেব ২ গ্রাম/লিটার বা কার্বেন্ডাজিম ১ গ্রাম/লিটার স্প্রে করুন। আক্রান্ত ফল সরিয়ে ধ্বংস করুন।', treatment_hi = 'हर 10 दिन में मैंकोजेब 2 ग्राम/लीटर या कार्बेन्डाजिम 1 ग्राम/लीटर स्प्रे करें। प्रभावित फलों को हटाकर नष्ट करें।' WHERE model_class_label = 'Papaya___Anthracnose';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Copper oxychloride @ 3g/L every 10 days. Avoid overhead watering. Remove severely affected leaves.', treatment_bn = 'প্রতি ১০ দিনে কপার অক্সিক্লোরাইড ৩ গ্রাম/লিটার স্প্রে করুন। উপর থেকে জল দেওয়া এড়িয়ে চলুন। মারাত্মক আক্রান্ত পাতা সরান।', treatment_hi = 'हर 10 दिन में कॉपर ऑक्सीक्लोराइड 3 ग्राम/लीटर स्प्रे करें। ऊपर से पानी देने से बचें। गंभीर प्रभावित पत्तियां हटाएं।' WHERE model_class_label = 'Papaya___Bacterial_Spot';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'No cure for viral curl. Control whitefly with Imidacloprid @ 0.3ml/L every 10 days. Remove infected plants.', treatment_bn = 'ভাইরাল কার্লের কোন প্রতিকার নেই। প্রতি ১০ দিনে ইমিডাক্লোপ্রিড ০.৩ মিলি/লিটার দিয়ে সাদা মাছি নিয়ন্ত্রণ করুন। আক্রান্ত গাছ সরান।', treatment_hi = 'वायरल कर्ल का कोई इलाज नहीं। हर 10 दिन में इमिडाक्लोप्रिड 0.3 मिली/लीटर से सफेद मक्खी नियंत्रित करें। संक्रमित पौधे हटाएं।' WHERE model_class_label = 'Papaya___Curl';
UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Papaya___Healthy';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Imidacloprid @ 0.3ml/L or release Ladybird beetles as biocontrol. Remove heavily infested leaves.', treatment_bn = 'ইমিডাক্লোপ্রিড ০.৩ মিলি/লিটার স্প্রে করুন বা লেডিবার্ড বিটল ছেড়ে দিন। মারাত্মক আক্রান্ত পাতা সরান।', treatment_hi = 'इमिडाक्लोप्रिड 0.3 मिली/लीटर स्प्रे करें या लेडीबर्ड बीटल छोड़ें। अत्यधिक प्रभावित पत्तियां हटाएं।' WHERE model_class_label = 'Papaya___Mealybug';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Wettable sulphur @ 3g/L or Dicofol 18.5% EC @ 2.5ml/L every 10 days. Increase humidity.', treatment_bn = 'প্রতি ১০ দিনে ভেজা সালফার ৩ গ্রাম/লিটার বা ডাইকোফল ১৮.৫% ইসি ২.৫ মিলি/লিটার স্প্রে করুন। আর্দ্রতা বাড়ান।', treatment_hi = 'हर 10 दिन में गीला सल्फर 3 ग्राम/लीटर या डाइकोफोल 18.5% EC 2.5 मिली/लीटर स्प्रे करें। नमी बढ़ाएं।' WHERE model_class_label = 'Papaya___Mite_Disease';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'No cure for viral mosaic. Uproot and burn infected plants. Control aphids with Dimethoate @ 2ml/L.', treatment_bn = 'ভাইরাল মোজাইকের কোন প্রতিকার নেই। আক্রান্ত গাছ উপড়ে পুড়িয়ে ফেলুন। ডাইমেথয়েট ২ মিলি/লিটার দিয়ে এফিড নিয়ন্ত্রণ করুন।', treatment_hi = 'वायरल मोज़ेक का कोई इलाज नहीं। संक्रमित पौधों को उखाड़कर जलाएं। डाइमेथोएट 2 मिली/लीटर से एफिड्स नियंत्रित करें।' WHERE model_class_label = 'Papaya___Mosaic';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'No cure. Remove and destroy infected plants. Use virus-free seeds. Control aphids.', treatment_bn = 'কোন প্রতিকার নেই। আক্রান্ত গাছ সরিয়ে ধ্বংস করুন। ভাইরাসমুক্ত বীজ ব্যবহার করুন। এফিড নিয়ন্ত্রণ করুন।', treatment_hi = 'कोई इलाज नहीं। संक्रमित पौधों को हटाकर नष्ट करें। वायरस-मुक्त बीज लगाएं। एफिड्स नियंत्रित करें।' WHERE model_class_label = 'Papaya___Ringspot';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Copper hydroxide @ 2g/L at leaf fall and bud break. Apply Oxytetracycline @ 0.5g/L during growing season.', treatment_bn = 'পাতা ঝরা এবং কুঁড়ি ফাটার সময় কপার হাইড্রক্সাইড ২ গ্রাম/লিটার স্প্রে করুন। ক্রমবর্ধমান মরসুমে অক্সিটেট্রাসাইক্লিন ০.৫ গ্রাম/লিটার প্রয়োগ করুন।', treatment_hi = 'पत्ती गिरने और कली खुलने पर कॉपर हाइड्रॉक्साइड 2 ग्राम/लीटर स्प्रे करें। बढ़ते मौसम में ऑक्सीटेट्रासाइक्लिन 0.5 ग्राम/लीटर डालें।' WHERE model_class_label = 'Peach___Bacterial_spot';
UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Peach___healthy';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Copper oxychloride @ 3g/L + Streptocycline @ 0.5g/L every 10 days. Avoid overhead watering.', treatment_bn = 'প্রতি ১০ দিনে কপার অক্সিক্লোরাইড ৩ গ্রাম/লিটার + স্ট্রেপ্টোসাইক্লিন ০.৫ গ্রাম/লিটার স্প্রে করুন। উপর থেকে জল দেওয়া এড়িয়ে চলুন।', treatment_hi = 'हर 10 दिन में कॉपर ऑक्सीक्लोराइड 3 ग्राम/लीटर + स्ट्रेप्टोसाइक्लिन 0.5 ग्राम/लीटर स्प्रे करें। ऊपर से पानी देने से बचें।' WHERE model_class_label = 'Pepper,_bell___Bacterial_spot';
