UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Chlorothalonil 75% WP @ 2g/L or Mancozeb @ 2.5g/L every 10 days. Ensure proper plant spacing and avoid overhead watering.', treatment_bn = 'প্রতি ১০ দিনে ক্লোরোথালোনিল ৭৫% ডব্লিউপি ২ গ্রাম/লিটার বা ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার স্প্রে করুন। সঠিক দূরত্ব বজায় রাখুন এবং উপর থেকে জল দেওয়া এড়িয়ে চলুন।', treatment_hi = 'हर 10 दिन में क्लोरोथालोनिल 75% WP 2 ग्राम/लीटर या मैंकोजेब 2.5 ग्राम/लीटर स्प्रे करें। उचित दूरी बनाए रखें और ऊपर से पानी देने से बचें।' WHERE model_class_label = 'Potato___Early_blight';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Spray Mancozeb 75% WP @ 2g/L or Metalaxyl+Mancozeb (Ridomil Gold) @ 2.5g/L every 7-10 days. Remove and destroy infected plants. Avoid overhead irrigation.', treatment_bn = 'প্রতি ৭-১০ দিনে ম্যাঙ্কোজেব ৭৫% ডব্লিউপি ২ গ্রাম/লিটার অথবা মেটালাক্সিল+ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার স্প্রে করুন। আক্রান্ত গাছ সরিয়ে ধ্বংস করুন। উপর থেকে সেচ এড়িয়ে চলুন।', treatment_hi = 'हर 7-10 दिन में मैंकोजेब 75% WP 2 ग्राम/लीटर या मेटालैक्सिल+मैंकोजेब 2.5 ग्राम/लीटर स्प्रे करें। संक्रमित पौधों को हटाकर नष्ट करें। ऊपर से सिंचाई से बचें।' WHERE model_class_label = 'Potato___Late_blight';
