UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Raspberry___healthy';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Drain the field for 2-3 days. Spray Copper hydroxide @ 2g/L + Streptocycline @ 0.3g/L. Use resistant varieties.', treatment_bn = '২-৩ দিন জমি নিষ্কাশন করুন। কপার হাইড্রক্সাইড ২ গ্রাম/লিটার + স্ট্রেপ্টোসাইক্লিন ০.৩ গ্রাম/লিটার স্প্রে করুন। প্রতিরোধী জাত ব্যবহার করুন।', treatment_hi = '2-3 दिन खेत सूखा रखें। कॉपर हाइड्रॉक्साइड 2 ग्राम/लीटर + स्ट्रेप्टोसाइक्लिन 0.3 ग्राम/लीटर स्प्रे करें। प्रतिरोधी किस्में लगाएं।' WHERE model_class_label = 'Rice___Bacterial_Leaf_Blight';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Soak seeds in Carbendazim @ 2g/L for 24 hours before sowing. Spray Mancozeb @ 2.5g/L or Carbendazim @ 1g/L at booting stage.', treatment_bn = 'বপনের আগে ২৪ ঘণ্টা কার্বেন্ডাজিম ২ গ্রাম/লিটার দ্রবণে বীজ ভিজিয়ে রাখুন। বুটিং পর্যায়ে ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার বা কার্বেন্ডাজিম ১ গ্রাম/লিটার স্প্রে করুন।', treatment_hi = 'बोने से पहले 24 घंटे कार्बेन्डाजिम 2 ग्राम/लीटर घोल में बीज भिगोएं। बूटिंग चरण में मैंकोजेब 2.5 ग्राम/लीटर या कार्बेन्डाजिम 1 ग्राम/लीटर स्प्रे करें।' WHERE model_class_label = 'Rice___Brown_Spot';
UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Rice___Healthy';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Spray Tricyclazole 75% WP @ 0.6g/L or Isoprothiolane 40% EC @ 1.5ml/L at neck emergence. Avoid excess nitrogen fertilizer.', treatment_bn = 'নেক ইমার্জেন্সে ট্রাইসাইক্লাজল ৭৫% ডব্লিউপি ০.৬ গ্রাম/লিটার বা আইসোপ্রোথিওলেন ৪০% ইসি ১.৫ মিলি/লিটার স্প্রে করুন। অতিরিক্ত নাইট্রোজেন সার এড়িয়ে চলুন।', treatment_hi = 'गर्दन निकलने पर ट्राइसाइक्लाजोल 75% WP 0.6 ग्राम/लीटर या आइसोप्रोथियोलेन 40% EC 1.5 मिली/लीटर स्प्रे करें। अतिरिक्त नाइट्रोजन उर्वरक से बचें।' WHERE model_class_label = 'Rice___Leaf_Blast';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Apply balanced fertilizer. Spray Carbendazim @ 1g/L or Mancozeb @ 2.5g/L every 15 days.', treatment_bn = 'সুষম সার প্রয়োগ করুন। প্রতি ১৫ দিনে কার্বেন্ডাজিম ১ গ্রাম/লিটার বা ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার স্প্রে করুন।', treatment_hi = 'संतुलित उर्वरक डालें। हर 15 दिन में कार्बेन्डाजिम 1 ग्राम/लीटर या मैंकोजेब 2.5 ग्राम/लीटर स्प्रे करें।' WHERE model_class_label = 'Rice___Leaf_Scald';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Spray Validamycin 3L @ 2ml/L or Hexaconazole 5% EC @ 2ml/L at booting stage. Reduce plant density.', treatment_bn = 'বুটিং পর্যায়ে ভ্যালিডামাইসিন ৩এল ২ মিলি/লিটার বা হেক্সাকোনাজল ৫% ইসি ২ মিলি/লিটার স্প্রে করুন। গাছের ঘনত্ব কমিয়ে দিন।', treatment_hi = 'बूटिंग चरण में वैलिडामाइसिन 3L 2 मिली/लीटर या हेक्साकोनाजोल 5% EC 2 मिली/लीटर स्प्रे करें। पौधों का घनत्व कम करें।' WHERE model_class_label = 'Rice___Sheath_Blight';
UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Soybean___healthy';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Wettable Sulphur @ 2g/L or Dinocap @ 1ml/L every 10 days. Improve air circulation.', treatment_bn = 'প্রতি ১০ দিনে ভেজা সালফার ২ গ্রাম/লিটার বা ডাইনোক্যাপ ১ মিলি/লিটার স্প্রে করুন। বায়ু চলাচল উন্নত করুন।', treatment_hi = 'हर 10 दिन में गीला सल्फर 2 ग्राम/लीटर या डाइनोकैप 1 मिली/लीटर स्प्रे करें। वायु संचार बढ़ाएं।' WHERE model_class_label = 'Squash___Powdery_mildew';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Captan @ 2g/L or Myclobutanil @ 1ml/L every 10-14 days. Remove affected leaves. Avoid overhead watering.', treatment_bn = 'প্রতি ১০-১৪ দিনে ক্যাপ্টান ২ গ্রাম/লিটার বা মাইক্লোবুটানিল ১ মিলি/লিটার স্প্রে করুন। আক্রান্ত পাতা সরান। উপর থেকে জল দেওয়া এড়িয়ে চলুন।', treatment_hi = 'हर 10-14 दिन में कैप्टन 2 ग्राम/लीटर या माइक्लोबुटानिल 1 मिली/लीटर स्प्रे करें। प्रभावित पत्तियां हटाएं। ऊपर से पानी देने से बचें।' WHERE model_class_label = 'Strawberry___Leaf_scorch';
UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Strawberry___healthy';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Apply Iron sulphate @ 10kg/acre. Grow resistant varieties. Avoid waterlogging.', treatment_bn = 'আয়রন সালফেট ১০ কেজি/একর প্রয়োগ করুন। প্রতিরোধী জাত চাষ করুন। জলাবদ্ধতা এড়িয়ে চলুন।', treatment_hi = 'आयरन सल्फेट 10 किग्रा/एकड़ डालें। प्रतिरोधी किस्में लगाएं। जलभराव से बचें।' WHERE model_class_label = 'Sugarcane___Banded_Chlorosis';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Mancozeb @ 2.5g/L or Propiconazole @ 1ml/L every 15 days. Remove affected lower leaves.', treatment_bn = 'প্রতি ১৫ দিনে ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার বা প্রোপিকোনাজল ১ মিলি/লিটার স্প্রে করুন। আক্রান্ত নিচের পাতা সরান।', treatment_hi = 'हर 15 दिन में मैंकोजेब 2.5 ग्राम/लीटर या प्रोपिकोनाजोल 1 मिली/लीटर स्प्रे करें। प्रभावित निचली पत्तियां हटाएं।' WHERE model_class_label = 'Sugarcane___Brown_Rust';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Carbendazim @ 1g/L or Mancozeb @ 2.5g/L every 15 days. Ensure balanced fertilization.', treatment_bn = 'প্রতি ১৫ দিনে কার্বেন্ডাজিম ১ গ্রাম/লিটার বা ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার স্প্রে করুন। সুষম সার নিশ্চিত করুন।', treatment_hi = 'हर 15 दिन में कार्बेन्डाजिम 1 ग्राम/लीटर या मैंकोजेब 2.5 ग्राम/लीटर स्प्रे करें। संतुलित उर्वरक सुनिश्चित करें।' WHERE model_class_label = 'Sugarcane___Brown_Spot';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Carbendazim @ 1g/L every 15 days. Use disease-free setts. Improve field sanitation.', treatment_bn = 'প্রতি ১৫ দিনে কার্বেন্ডাজিম ১ গ্রাম/লিটার স্প্রে করুন। রোগমুক্ত সেট ব্যবহার করুন। মাঠের স্যানিটেশন উন্নত করুন।', treatment_hi = 'हर 15 दिन में कार्बेन्डाजिम 1 ग्राम/लीटर स्प्रे करें। रोग-मुक्त सेट लगाएं। खेत की स्वच्छता सुधारें।' WHERE model_class_label = 'Sugarcane___Colletotrichosis';
UPDATE diseases SET severity = 'LOW', treatment_en = 'Normal ageing of lower leaves. Remove dried leaves to prevent pest hiding. No chemical treatment needed.', treatment_bn = 'নিচের পাতার স্বাভাবিক বার্ধক্য। কীটপতঙ্গ লুকানো রোধ করতে শুকনো পাতা সরান। রাসায়নিক চিকিৎসার প্রয়োজন নেই।', treatment_hi = 'निचली पत्तियों की सामान्य उम्र बढ़ना। कीटों को छिपने से रोकने के लिए सूखी पत्तियां हटाएं। रासायनिक उपचार की आवश्यकता नहीं।' WHERE model_class_label = 'Sugarcane___Dried_Leaves';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Remove and destroy affected clumps. Control leafhoppers with Imidacloprid @ 0.3ml/L. Use healthy setts.', treatment_bn = 'আক্রান্ত গুচ্ছ সরিয়ে ধ্বংস করুন। ইমিডাক্লোপ্রিড ০.৩ মিলি/লিটার দিয়ে লিফহপার নিয়ন্ত্রণ করুন। সুস্থ সেট ব্যবহার করুন।', treatment_hi = 'प्रभावित गुच्छों को हटाकर नष्ट करें। इमिडाक्लोप्रिड 0.3 मिली/लीटर से लीफहॉपर नियंत्रित करें। स्वस्थ सेट लगाएं।' WHERE model_class_label = 'Sugarcane___Grassy_Shoot';
UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Sugarcane___Healthy';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Use virus-free setts. Control aphids with Dimethoate @ 2ml/L. Remove and destroy infected plants.', treatment_bn = 'ভাইরাসমুক্ত সেট ব্যবহার করুন। ডাইমেথয়েট ২ মিলি/লিটার দিয়ে এফিড নিয়ন্ত্রণ করুন। আক্রান্ত গাছ সরিয়ে ধ্বংস করুন।', treatment_hi = 'वायरस-मुक्त सेट लगाएं। डाइमेथोएट 2 मिली/लीटर से एफिड्स को नियंत्रित करें। संक्रमित पौधों को हटाकर नष्ट करें।' WHERE model_class_label = 'Sugarcane___Mosaic';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Carbendazim @ 1g/L. Improve field drainage. Remove severely affected plants.', treatment_bn = 'কার্বেন্ডাজিম ১ গ্রাম/লিটার স্প্রে করুন। জমির নিষ্কাশন উন্নত করুন। মারাত্মকভাবে আক্রান্ত গাছ সরান।', treatment_hi = 'कार्बेन्डाजिम 1 ग्राम/लीटर स्प्रे करें। खेत की जल निकासी सुधारें। गंभीर रूप से प्रभावित पौधे हटाएं।' WHERE model_class_label = 'Sugarcane___Pokkah_Boeng';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Uproot and burn infected clumps. Use resistant varieties. Treat setts with Carbendazim @ 1g/L for 15 minutes before planting.', treatment_bn = 'আক্রান্ত গুচ্ছ উপড়ে পুড়িয়ে ফেলুন। প্রতিরোধী জাত ব্যবহার করুন। রোপণের আগে ১৫ মিনিট কার্বেন্ডাজিম ১ গ্রাম/লিটার দ্রবণে সেট শোধন করুন।', treatment_hi = 'संक्रमित गुच्छों को उखाड़कर जलाएं। प्रतिरोधी किस्में उगाएं। बोने से पहले 15 मिनट कार्बेन्डाजिम 1 ग्राम/लीटर घोल में सेट उपचार करें।' WHERE model_class_label = 'Sugarcane___Red_Rot';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Mancozeb @ 2.5g/L or Propiconazole @ 1ml/L every 15 days. Remove affected lower leaves.', treatment_bn = 'প্রতি ১৫ দিনে ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার বা প্রোপিকোনাজল ১ মিলি/লিটার স্প্রে করুন। আক্রান্ত নিচের পাতা সরান।', treatment_hi = 'हर 15 दिन में मैंकोजेब 2.5 ग्राम/लीटर या प्रोपिकोनाजोल 1 मिली/लीटर स्प्रे करें। प्रभावित निचली पत्तियां हटाएं।' WHERE model_class_label = 'Sugarcane___Rust';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Sugarcane Mosaic Virus – no cure. Remove and destroy infected plants. Control aphids with Dimethoate @ 2ml/L.', treatment_bn = 'আখ মোজাইক ভাইরাস – কোন প্রতিকার নেই। আক্রান্ত গাছ সরিয়ে ধ্বংস করুন। ডাইমেথয়েট ২ মিলি/লিটার দিয়ে এফিড নিয়ন্ত্রণ করুন।', treatment_hi = 'गन्ना मोज़ेक वायरस – कोई इलाज नहीं। संक्रमित पौधों को हटाकर नष्ट करें। डाइमेथोएट 2 मिली/लीटर से एफिड्स नियंत्रित करें।' WHERE model_class_label = 'Sugarcane___SCMV';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Sugarcane Yellow Leaf Virus – no cure. Use virus-free setts. Control aphids. Remove infected plants.', treatment_bn = 'আখ হলুদ পাতা ভাইরাস – কোন প্রতিকার নেই। ভাইরাসমুক্ত সেট ব্যবহার করুন। এফিড নিয়ন্ত্রণ করুন। আক্রান্ত গাছ সরান।', treatment_hi = 'गन्ना पीला पत्ती वायरस – कोई इलाज नहीं। वायरस-मुक्त सेट लगाएं। एफिड्स नियंत्रित करें। संक्रमित पौधे हटाएं।' WHERE model_class_label = 'Sugarcane___SCYLV';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Treat setts with Carbendazim @ 1g/L for 15 minutes before planting. Avoid waterlogged fields.', treatment_bn = 'রোপণের আগে ১৫ মিনিট কার্বেন্ডাজিম ১ গ্রাম/লিটার দ্রবণে সেট শোধন করুন। জলাবদ্ধ জমি এড়িয়ে চলুন।', treatment_hi = 'बोने से पहले 15 मिनट कार्बेन्डाजिम 1 ग्राम/लीटर घोल में सेट उपचार करें। जलभराव वाले खेतों से बचें।' WHERE model_class_label = 'Sugarcane___Sett_Rot';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Remove smutted canes with whips and burn immediately. Use disease-free setts from certified nurseries.', treatment_bn = 'হুইপ সহ স্মাটেড আখ সরিয়ে অবিলম্বে পুড়িয়ে ফেলুন। প্রত্যয়িত নার্সারি থেকে রোগমুক্ত সেট ব্যবহার করুন।', treatment_hi = 'व्हिप सहित स्मटेड गन्ने को हटाकर तुरंत जलाएं। प्रमाणित नर्सरी से रोग-मुक्त सेट लगाएं।' WHERE model_class_label = 'Sugarcane___Smut';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'No cure. Uproot and burn infected plants. Control vectors (aphids, leafhoppers). Use disease-free setts.', treatment_bn = 'কোন প্রতিকার নেই। আক্রান্ত গাছ উপড়ে পুড়িয়ে ফেলুন। বাহক (এফিড, লিফহপার) নিয়ন্ত্রণ করুন। রোগমুক্ত সেট ব্যবহার করুন।', treatment_hi = 'कोई इलाज नहीं। संक्रमित पौधों को उखाड़कर जलाएं। वाहक (एफिड्स, लीफहॉपर) नियंत्रित करें। रोग-मुक्त सेट लगाएं।' WHERE model_class_label = 'Sugarcane___Viral_Disease';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Apply Iron sulphate @ 10kg/acre. Improve drainage. Grow resistant varieties.', treatment_bn = 'আয়রন সালফেট ১০ কেজি/একর প্রয়োগ করুন। নিষ্কাশন উন্নত করুন। প্রতিরোধী জাত চাষ করুন।', treatment_hi = 'आयरन सल्फेट 10 किग्रा/एकड़ डालें। जल निकासी सुधारें। प्रतिरोधी किस्में उगाएं।' WHERE model_class_label = 'Sugarcane___Yellow';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Use disease-free setts. Control leafhoppers with Imidacloprid @ 0.3ml/L. Remove and destroy infected clumps.', treatment_bn = 'রোগমুক্ত সেট ব্যবহার করুন। ইমিডাক্লোপ্রিড ০.৩ মিলি/লিটার দিয়ে লিফহপার নিয়ন্ত্রণ করুন। আক্রান্ত গুচ্ছ সরিয়ে ধ্বংস করুন।', treatment_hi = 'रोग-मुक्त सेट लगाएं। इमिडाक्लोप्रिड 0.3 मिली/लीटर से लीफहॉपर नियंत्रित करें। संक्रमित गुच्छों को हटाकर नष्ट करें।' WHERE model_class_label = 'Sugarcane___Yellow_Leaf';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Copper oxychloride 50% WP @ 3g/L + Streptocycline @ 0.5g/L every 10 days. Avoid working with wet plants.', treatment_bn = 'প্রতি ১০ দিনে কপার অক্সিক্লোরাইড ৫০% ডব্লিউপি ৩ গ্রাম/লিটার + স্ট্রেপ্টোসাইক্লিন ০.৫ গ্রাম/লিটার স্প্রে করুন। ভেজা গাছ নিয়ে কাজ করা এড়িয়ে চলুন।', treatment_hi = 'हर 10 दिन में कॉपर ऑक्सीक्लोराइड 50% WP 3 ग्राम/लीटर + स्ट्रेप्टोसाइक्लिन 0.5 ग्राम/लीटर स्प्रे करें। गीले पौधों के साथ काम करने से बचें।' WHERE model_class_label = 'Tomato___Bacterial_spot';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Chlorothalonil 75% WP @ 2g/L or Mancozeb @ 2.5g/L every 10 days. Prune lower leaves for air circulation.', treatment_bn = 'প্রতি ১০ দিনে ক্লোরোথালোনিল ৭৫% ডব্লিউপি ২ গ্রাম/লিটার বা ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার স্প্রে করুন। বায়ু চলাচলের জন্য নিচের পাতা ছাঁটাই করুন।', treatment_hi = 'हर 10 दिन में क्लोरोथालोनिल 75% WP 2 ग्राम/लीटर या मैंकोजेब 2.5 ग्राम/लीटर स्प्रे करें। हवा के लिए निचली पत्तियां छांटें।' WHERE model_class_label = 'Tomato___Early_blight';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Spray Metalaxyl+Mancozeb @ 2.5g/L or Cymoxanil+Mancozeb @ 3g/L every 7 days. Remove and destroy infected leaves. Avoid overhead watering.', treatment_bn = 'প্রতি ৭ দিনে মেটালাক্সিল+ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার বা সাইমোক্সানিল+ম্যাঙ্কোজেব ৩ গ্রাম/লিটার স্প্রে করুন। আক্রান্ত পাতা সরিয়ে ধ্বংস করুন। উপর থেকে জল দেওয়া এড়িয়ে চলুন।', treatment_hi = 'हर 7 दिन में मेटालैक्सिल+मैंकोजेब 2.5 ग्राम/लीटर या साइमोक्सानिल+मैंकोजेब 3 ग्राम/लीटर स्प्रे करें। संक्रमित पत्तियों को हटाकर नष्ट करें। ऊपर से पानी देने से बचें।' WHERE model_class_label = 'Tomato___Late_blight';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Improve ventilation. Spray Mancozeb @ 2.5g/L or Chlorothalonil @ 2g/L every 10 days.', treatment_bn = 'বায়ুচলাচল উন্নত করুন। প্রতি ১০ দিনে ম্যাঙ্কোজেব ২.৫ গ্রাম/লিটার বা ক্লোরোথালোনিল ২ গ্রাম/লিটার স্প্রে করুন।', treatment_hi = 'वेंटिलेशन में सुधार करें। हर 10 दिन में मैंकोजेब 2.5 ग्राम/लीटर या क्लोरोथालोनिल 2 ग्राम/लीटर स्प्रे करें।' WHERE model_class_label = 'Tomato___Leaf_Mold';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Chlorothalonil @ 2g/L or Copper fungicide @ 3g/L every 10 days. Remove lower infected leaves.', treatment_bn = 'প্রতি ১০ দিনে ক্লোরোথালোনিল ২ গ্রাম/লিটার বা কপার ছত্রাকনাশক ৩ গ্রাম/লিটার স্প্রে করুন। নিচের আক্রান্ত পাতা সরান।', treatment_hi = 'हर 10 दिन में क्लोरोथालोनिल 2 ग्राम/लीटर या कॉपर कवकनाशी 3 ग्राम/लीटर स्प्रे करें। निचली संक्रमित पत्तियां हटाएं।' WHERE model_class_label = 'Tomato___Septoria_leaf_spot';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Dicofol 18.5% EC @ 2.5ml/L or Wettable sulphur @ 3g/L every 10 days. Increase humidity around plants.', treatment_bn = 'প্রতি ১০ দিনে ডাইকোফল ১৮.৫% ইসি ২.৫ মিলি/লিটার বা ভেজা সালফার ৩ গ্রাম/লিটার স্প্রে করুন। গাছের চারপাশে আর্দ্রতা বাড়ান।', treatment_hi = 'हर 10 दिन में डाइकोफोल 18.5% EC 2.5 मिली/लीटर या गीला सल्फर 3 ग्राम/लीटर स्प्रे करें। पौधों के आसपास नमी बढ़ाएं।' WHERE model_class_label = 'Tomato___Spider_mites Two-spotted_spider_mite';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Spray Chlorothalonil @ 2g/L or Azoxystrobin @ 1ml/L every 10 days. Remove crop debris after harvest.', treatment_bn = 'প্রতি ১০ দিনে ক্লোরোথালোনিল ২ গ্রাম/লিটার বা অ্যাজোক্সিস্ট্রোবিন ১ মিলি/লিটার স্প্রে করুন। ফসল কাটার পর ধ্বংসাবশেষ সরান।', treatment_hi = 'हर 10 दिन में क्लोरोथालोनिल 2 ग्राम/लीटर या एज़ोक्सीस्ट्रोबिन 1 मिली/लीटर स्प्रे करें। कटाई के बाद मलबा हटाएं।' WHERE model_class_label = 'Tomato___Target_Spot';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'No direct cure. Uproot and destroy infected plants immediately. Control whitefly with Imidacloprid @ 0.3ml/L every 10 days.', treatment_bn = 'সরাসরি প্রতিকার নেই। আক্রান্ত গাছ অবিলম্বে উপড়ে ফেলে ধ্বংস করুন। প্রতি ১০ দিনে ইমিডাক্লোপ্রিড ০.৩ মিলি/লিটার দিয়ে সাদা মাছি নিয়ন্ত্রণ করুন।', treatment_hi = 'कोई सीधा इलाज नहीं। संक्रमित पौधों को तुरंत उखाड़कर नष्ट करें। हर 10 दिन में इमिडाक्लोप्रिड 0.3 मिली/लीटर से सफेद मक्खी को नियंत्रित करें।' WHERE model_class_label = 'Tomato___Tomato_Yellow_Leaf_Curl_Virus';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'No cure. Remove and burn infected plants. Disinfect tools. Control aphids with Dimethoate @ 2ml/L.', treatment_bn = 'কোন প্রতিকার নেই। আক্রান্ত গাছ সরিয়ে পুড়িয়ে ফেলুন। যন্ত্রপাতি জীবাণুমুক্ত করুন। ডাইমেথয়েট ২ মিলি/লিটার দিয়ে এফিড নিয়ন্ত্রণ করুন।', treatment_hi = 'कोई इलाज नहीं। संक्रमित पौधों को हटाकर जला दें। उपकरणों को कीटाणुरहित करें। डाइमेथोएट 2 मिली/लीटर से एफिड्स को नियंत्रित करें।' WHERE model_class_label = 'Tomato___Tomato_mosaic_virus';
UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Tomato___healthy';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Spray Propiconazole 25% EC @ 1ml/L or Tebuconazole 25.9% EC @ 1ml/L at first sign. Repeat after 15 days.', treatment_bn = 'প্রথম লক্ষণে প্রোপিকোনাজল ২৫% ইসি ১ মিলি/লিটার বা টেবুকোনাজল ২৫.৯% ইসি ১ মিলি/লিটার স্প্রে করুন। ১৫ দিন পর পুনরাবৃত্তি করুন।', treatment_hi = 'पहले लक्षण पर प्रोपिकोनाजोल 25% EC 1 मिली/लीटर या टेबुकोनाजोल 25.9% EC 1 मिली/लीटर स्प्रे करें। 15 दिन बाद दोहराएं।' WHERE model_class_label = 'Wheat___Brown_Rust';
UPDATE diseases SET severity = 'LOW', treatment_en = 'The plant appears healthy. Continue good agricultural practices.', treatment_bn = 'গাছটি সুস্থ দেখাচ্ছে। ভালো কৃষি অনুশীলন চালিয়ে যান।', treatment_hi = 'पौधा स्वस्थ दिख रहा है। अच्छी कृषि पद्धतियां जारी रखें।' WHERE model_class_label = 'Wheat___Healthy';
UPDATE diseases SET severity = 'MEDIUM', treatment_en = 'Treat seeds with Carboxin 37.5% + Thiram 37.5% @ 2.5g/kg before sowing. Remove and burn infected heads.', treatment_bn = 'বপনের আগে কার্বক্সিন ৩৭.৫% + থাইরাম ৩৭.৫% ২.৫ গ্রাম/কেজি হারে বীজ শোধন করুন। আক্রান্ত শীষ সরিয়ে পুড়িয়ে ফেলুন।', treatment_hi = 'बोने से पहले कार्बोक्सिन 37.5% + थायरम 37.5% 2.5 ग्राम/किग्रा से बीजोपचार करें। संक्रमित बालियों को हटाकर जलाएं।' WHERE model_class_label = 'Wheat___Loose_Smut';
UPDATE diseases SET severity = 'HIGH', treatment_en = 'Spray Propiconazole 25% EC @ 1ml/L immediately. Grow rust-resistant wheat varieties.', treatment_bn = 'অবিলম্বে প্রোপিকোনাজল ২৫% ইসি ১ মিলি/লিটার স্প্রে করুন। মরিচা প্রতিরোধী গমের জাত চাষ করুন।', treatment_hi = 'तुरंत प्रोपिकोनाजोल 25% EC 1 मिली/लीटर स्प्रे करें। जंग-प्रतिरोधी गेहूं की किस्में उगाएं।' WHERE model_class_label = 'Wheat___Yellow_Rust';

COMMIT;